function modelPath = f90_xbatt02_build_reference( ...
        outDir,behaviorProfilePath)
%F90_XBATT02_BUILD_REFERENCE Build an independently authored derived golden.
%
% The source behavior profile is a required behavioral-compatibility gate.
% No upstream blocks, callbacks, masks or model code are copied.
arguments
    outDir (1,1) string = ...
        fullfile(getenv("SIMUVERITY_TASK_ROOT"), "reference", "files")
    behaviorProfilePath (1,1) string = ...
        string(getenv("SIMUVERITY_TASK_ROOT"))
end

assert(isfile(behaviorProfilePath), ...
    "F90_XBATT02_BEHAVIOR_PROFILE_MISSING");
profile = jsondecode(fileread(behaviorProfilePath));
if isfield(profile,"source") && ...
        isfield(profile.source,"behavior_profile")
    compactProfile = profile.source.behavior_profile;
    profileValid = string(compactProfile.generation_run_id) == ...
        "f90xbatt02_behaviorprofile_20260726_c_03" && ...
        compactProfile.time_seconds(1) == 0 && ...
        compactProfile.time_seconds(2) == 2400 && ...
        compactProfile.discharge_and_regeneration_present && ...
        compactProfile.simscape_log_present && ...
        strcmpi(string(profile.source.file_presence), ...
        "present");
else
    profileValid = profile.pass && ...
        profile.exact_source_unchanged && ...
        profile.behavior.four_timeseries_cover_full_horizon;
end
assert(profileValid,"F90_XBATT02_BEHAVIOR_PROFILE_NOT_VALID");

def = f90_xbatt02_definition;
if ~isfolder(outDir), mkdir(outDir); end
modelName = "XBATT02_reference";
modelPath = fullfile(outDir,modelName + ".slx");
if bdIsLoaded(modelName), close_system(modelName,0); end
if isfile(modelPath), delete(modelPath); end

new_system(modelName,"Model");
cleanup = onCleanup(@() local_close(modelName)); %#ok<NASGU>
set_param(modelName, ...
    "SolverType","Fixed-step", ...
    "Solver","FixedStepDiscrete", ...
    "FixedStep",num2str(def.sim.step,17), ...
    "StartTime","0", ...
    "StopTime",num2str(def.sim.stop,17), ...
    "ReturnWorkspaceOutputs","on", ...
    "SignalLogging","off", ...
    "ModelBrowserVisibility","off");

add_block("simulink/Sources/Digital Clock",modelName+"/Time", ...
    "SampleTime",num2str(def.sim.step,17), ...
    "Position",[25 35 90 65]);

for index = 1:numel(def.public_inputs)
    input = def.public_inputs(index);
    assignin("base",input.name,input.nominal);
    add_block("simulink/Sources/Constant", ...
        modelName+"/Input_"+input.name, ...
        "Value",input.name, ...
        "Position",[25 75+42*index 180 100+42*index]);
end

plant = modelName + "/CausalElectroThermalPackAndControl";
add_block("simulink/User-Defined Functions/MATLAB Function",plant, ...
    "Position",[270 35 640 440]);
chart = find(sfroot,"-isa","Stateflow.EMChart","Path",char(plant));
assert(~isempty(chart),"F90_XBATT02_REFERENCE_CHART_MISSING");
kernelPath = fullfile(fileparts(mfilename("fullpath")), ...
    "f90_xbatt02_reference_kernel.m");
chart.Script = fileread(kernelPath);

set_param(modelName,"SimulationCommand","update");
add_line(modelName,"Time/1", ...
    "CausalElectroThermalPackAndControl/1","autorouting","on");
for index = 1:numel(def.public_inputs)
    add_line(modelName,"Input_"+def.public_inputs(index).name+"/1", ...
        "CausalElectroThermalPackAndControl/"+(index+1), ...
        "autorouting","on");
end

for index = 1:numel(def.outputs)
    output = def.outputs(index);
    y = 65+88*index;
    add_block("simulink/Sinks/To Workspace", ...
        modelName+"/Log_"+output.name, ...
        "VariableName",output.name, ...
        "SaveFormat","Timeseries", ...
        "MaxDataPoints","inf", ...
        "SampleTime","-1", ...
        "Position",[735 y 885 y+28]);
    add_block("simulink/Sinks/Out1", ...
        modelName+"/Out_"+output.name, ...
        "Port",num2str(index), ...
        "Position",[950 y 985 y+22]);
    add_line(modelName, ...
        "CausalElectroThermalPackAndControl/"+index, ...
        "Log_"+output.name+"/1","autorouting","on");
    add_line(modelName, ...
        "CausalElectroThermalPackAndControl/"+index, ...
        "Out_"+output.name+"/1","autorouting","on");
end

annotation = Simulink.Annotation(modelName, ...
    "F90-XBATT-02 | independent mixed-module electro-thermal pack | source behavior validated");
annotation.Position = [270 5 850 25];
set_param(modelName,"Description", ...
    "Independent derived golden. Uses measured-state current supervision, distributed thermal balances, branch coolant enthalpy, and same-pack pump auxiliary current. No upstream model blocks or code are copied.");
set_param(modelName,"SimulationCommand","update");
save_system(modelName,modelPath);
fprintf("F90_XBATT02_BUILD_REFERENCE path=%s behavior_profile=%s\n", ...
    modelPath,behaviorProfilePath);
end

function local_close(model)
try
    if bdIsLoaded(model), close_system(model,0); end
catch
end
end
